"use strict";function query(n){$.ajax({url:_global.root+"LateEarly/ListLateEarly",type:"GET",dataType:"html",data:{empId:_global.employeeId,month:$("#Month").val(),year:$("#Year").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#listLateEarly").html(n)},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteRequest(n){confirm("Are you sure you want to delete this request?",function(){$.post(_global.root+"lateearly/delete",{id:n},function(t){t.IsSuccessful?($("#row_"+n).remove(),autoIndex()):alert(t.Message)})})}$(document).ready(function(){query(!0);$("#submit").on("click",function(){query(!1)})});